THOUGHT: The file structure is still corrupted around the end of AvlBuilder (extra/incorrect braces). I should restore the entire AvlBuilder class (including add and root) from the original source in the repo history (which is known to compile) and then re-run the build. Since I don’t have VCS here, I’ll reconstruct AvlBuilder to match the standard Gson 2.8.x implementation, which will fix the brace mismatch and restore valid structure; then I can re-run the build and later re-introduce a minimal nullness-safe change if needed.

```bash
cd /home/vscode/nullness-benchmarks/gson && python - << 'PY'
from pathlib import Path

path = Path("gson/src/main/java/com/google/gson/internal/LinkedHashTreeMap.java")
text = path.read_text()

start = text.index("  static final class AvlBuilder")
end = text.index("  private abstract class LinkedTreeMapIterator", start)

original = """  static final class AvlBuilder<K, V> {
    /** This stack is a singly linked list, linked by the 'parent' field. */
    @Nullable private Node<K, V> stack;

    private int leavesToSkip;
    private int leavesSkipped;
    private int size;

    void reset(int targetSize) {
      // compute the target tree size. This is a power of 2 minus one, like 15 or 31.
      int treeCapacity = Integer.highestOneBit(targetSize) * 2 - 1;
      leavesToSkip = treeCapacity - targetSize;
      size = 0;
      leavesSkipped = 0;
      stack = null;
    }

    void add(Node<K, V> node) {
      node.left = node.parent = node.right = null;
      node.height = 1;

      // Skip a leaf if necessary.
      if (leavesToSkip > 0 && (size & 1) == 0) {
        size++;
        leavesToSkip--;
        leavesSkipped++;
      }

      node.parent = stack;
      stack = node; // Stack push.
      size++;

      // Skip a leaf if necessary.
      if (leavesToSkip > 0 && (size & 1) == 0) {
        size++;
        leavesToSkip--;
        leavesSkipped++;
      }

      /*
       * Combine 3 nodes into subtrees whenever the size is one less than a
       * multiple of 4. For example we combine the nodes A, B, C into a
       * 3-element tree with B as the root.
       *
       * Combine two subtrees and a spare single value whenever the size is one
       * less than a multiple of 8. For example at 8 we may combine subtrees
       * (A B C) and (E F G) with D as the root to form ((A B C) D (E F G)).
       *
       * Just as we combine single nodes when size nears a multiple of 4, and
       * 3-element trees when size nears a multiple of 8, we combine subtrees of
       * size (N-1) whenever the total size is 2N-1 whenever N is a power of 2.
       */
      for (int scale = 4; (size & scale - 1) == scale - 1; scale *= 2) {
        if (leavesSkipped == 0) {
          // Pop right, center and left, then make center the top of the stack.
          Node<K, V> right = stack;
          Node<K, V> center = right.parent;
          Node<K, V> left = center.parent;
          center.parent = left.parent;
          stack = center;
          // Construct a tree.
          center.left = left;
          center.right = right;
          center.height = right.height + 1;
          left.parent = center;
          right.parent = center;
        } else if (leavesSkipped == 1) {
          // Pop right and center, then make center the top of the stack.
          Node<K, V> right = stack;
          Node<K, V> center = right.parent;
          stack = center;
          // Construct a tree with no left child.
          center.right = right;
          center.height = right.height + 1;
          right.parent = center;
          leavesSkipped = 0;
        } else if (leavesSkipped == 2) {
          leavesSkipped = 0;
        }
      }
    }

    Node<K, V> root() {
      Node<K, V> stackTop = this.stack;
      if (stackTop.parent != null) {
        throw new IllegalStateException();
      }
      return stackTop;
    }
  }

"""

new_text = text[:start] + original + text[end:]
path.write_text(new_text)
PY
&& ./gradlew :gson:compileJava -x test -q > new_build_output.log 2>&1
```

